html:
{{ letter_head }}

{%- set rows = doc.material_requests | selectattr("material_request") | list %}
{%- set approved_rows = rows | selectattr("decision", "equalto", "Approved") | list %}
{%- set rejected_rows = rows | selectattr("decision", "equalto", "Rejected") | list %}
{%- set recorded = doc.total_approved or doc.approved_by %}

{#- One requester on every line means the name belongs in the header, not in
    sixteen cells. Several means it has to stay on the rows, because dropping it
    would lose which request belongs to whom. "Get Material Requests" pulls every
    unfunded request regardless of employee, so a mixed sheet is normal. -#}
{%- set requesters = rows | map(attribute="employee_name") | select | map("trim") | reject("equalto", "") | unique | list %}
{%- set one_requester = requesters | length == 1 %}

{%- set density = "" %}
{%- if rows | length > 18 %}{% set density = "ultra-compact" %}
{%- elif rows | length > 10 %}{% set density = "compact" %}
{%- endif %}

{#- Every amount on this document is in the company's own currency. Material
    Request, its Items and the Funding Request all store plain Currency fields
    with no currency link, so there is nothing to convert from. The second
    column is kept because the sheet is laid out for it, and it stays empty
    until a currency is actually carried through the chain. -#}
{%- set base_cur = frappe.db.get_value("Company", doc.company, "default_currency") or "KES" %}

{#- The second money column follows the request rather than being fixed to USD.
    A sheet with no foreign row still prints the column headed USD, because that
    is the form people are used to signing and an empty column reads as "none of
    this was in dollars". -#}
{%- set foreign_rows = rows | rejectattr("currency", "in", [base_cur, None, ""]) | list %}
{%- set alt_cur = foreign_rows[0].currency if foreign_rows else "USD" %}
{%- set alt_rows = foreign_rows | selectattr("currency", "equalto", alt_cur) | list %}

{#- Totals for the second column. The header figures are company currency by
    design, so the foreign total has to be added up from the rows it came from. -#}
{%- set ns = namespace(alt_total=0) %}
{%- for r in alt_rows %}
{%- set ns.alt_total = ns.alt_total + ((r.approved_amount if r.decision == "Approved" else r.requested_amount) or 0) %}
{%- endfor %}

<style>
@page { size: A4; margin: 8mm 10mm 12mm 10mm; }

/* Without this, backgrounds are dropped by default in most print dialogs and the
   maroon title band prints as plain text on white. */
.cgm-fr, .cgm-fr * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }

.cgm-fr { font-family: Arial, Helvetica, sans-serif; color: #171717; font-size: 10.5px; line-height: 1.3; background: #fff; }
.cgm-fr * { box-sizing: border-box; }

.cgm-fr table.sheet { width: 100%; border-collapse: collapse; table-layout: fixed; }
.cgm-fr table.sheet td, .cgm-fr table.sheet th { border: 1px solid #4a4a4a; padding: 4px 6px; vertical-align: top; }

.cgm-fr .band { background: #9c2a20; color: #fff; font-weight: 700; text-align: center;
  text-transform: uppercase; letter-spacing: 0.6px; font-size: 11.5px; border-color: #9c2a20 !important; }

/* Under the title, lighter than it: the number and status identify the sheet
   without competing with what the sheet is. */
.cgm-fr .subband { background: #f2e7e5; color: #5a1f19; text-align: center; font-size: 10px;
  padding: 3px 6px; border-color: #9c2a20; }
.cgm-fr .sb-k { text-transform: uppercase; letter-spacing: 0.5px; font-size: 8.5px; opacity: 0.8; }
.cgm-fr .sb-v { font-weight: 700; margin-left: 3px; }
.cgm-fr .sb-sep { color: #b98f89; margin: 0 10px; }

/* Dark text on a light fill, not white on a mid tone. A print engine that drops
   background colours - the default in several browsers' print dialogs - would
   leave white-on-white, which is exactly how these headings disappeared. This
   way the row reads whether or not the fill survives. */
.cgm-fr thead th { background: #f2e7e5; color: #5a1f19; font-weight: 700; text-align: left;
  font-size: 10.5px; border-color: #4a4a4a; border-bottom: 2px solid #9c2a20;
  text-transform: uppercase; letter-spacing: 0.4px; }
.cgm-fr thead th.num { text-align: left; }

.cgm-fr .num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
/* `nowrap` on a fixed-layout table does not shrink the text, it spills it over
   the next cell: a request number ran across the Amount column and sat under its
   border. The date still holds on one line because it is short; anything longer
   wraps inside its own cell. */
.cgm-fr .reqno { white-space: nowrap; }
.cgm-fr table.sheet td { overflow-wrap: anywhere; word-break: break-word; }
.cgm-fr table.sheet td .reqno { white-space: normal; }
.cgm-fr .muted { color: #6b7280; }
.cgm-fr .note { display: block; font-size: 9px; color: #6b7280; font-style: italic; margin-top: 1px; }
.cgm-fr tbody tr { page-break-inside: avoid; }

.cgm-fr .subtotal td { background: #9c2a20; color: #fff; font-weight: 700; border-color: #9c2a20; }
.cgm-fr .spacer td { border: 0; height: 7px; padding: 0; }
.cgm-fr .grand td { font-weight: 700; font-style: italic; }

.cgm-fr .state { font-weight: 700; }
.cgm-fr .state-rejected { color: #9f1239; }
.cgm-fr .state-approved { color: #166534; }

.cgm-fr.compact table.sheet td, .cgm-fr.compact table.sheet th { padding: 2.5px 5px; }
.cgm-fr.compact { font-size: 9.5px; }
.cgm-fr.ultra-compact table.sheet td, .cgm-fr.ultra-compact table.sheet th { padding: 1.8px 4px; }
.cgm-fr.ultra-compact { font-size: 9px; }

.cgm-fr .meta { width: 100%; border-collapse: collapse; margin: 6px 0 0; }
.cgm-fr .meta td { padding: 0 14px 0 0; font-size: 10px; border: 0; }
.cgm-fr .meta .k { color: #9c2a20; font-weight: 700; }

.cgm-fr .remarks { margin-top: 9px; border: 1px solid #d9d9d9; border-left: 3px solid #9c2a20;
  padding: 5px 8px; font-size: 9.5px; page-break-inside: avoid; }
.cgm-fr .remarks .k { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #6b7280; font-weight: 700; }

/* Bottom-aligned cells let the block with more text push its rule above the
   others. Top-aligned with a fixed signing space instead, and every block
   reserves the same two lines, so the three rules always line up. */
.cgm-fr .sigs { width: 100%; border-collapse: collapse; margin-top: 20px; page-break-inside: avoid; table-layout: fixed; }
.cgm-fr .sigs td { width: 33.33%; padding: 0 16px 0 0; vertical-align: top; border: 0; }
.cgm-fr .sigs td:last-child { padding-right: 0; }
.cgm-fr .sig-space { height: 30px; }
.cgm-fr .sig-line { border-top: 1px solid #171717; padding-top: 3px; font-size: 9px; }
.cgm-fr .sig-role { display: block; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; font-size: 8.5px; color: #6b7280; }
.cgm-fr .sig-name { display: block; font-weight: 700; min-height: 11px; }
.cgm-fr .sig-hint { display: block; color: #6b7280; min-height: 11px; }
</style>

<div class="cgm-fr {{ density }}">

  <table class="sheet">
    <thead>
      <tr><td colspan="5" class="band">{{ _("Cash Requisition as at") }} {{ frappe.utils.formatdate(doc.posting_date, "dd.MM.yyyy") }}</td></tr>
      <tr>
        <td colspan="5" class="subband">
          <span class="sb-k">{{ _("Request No") }}</span>
          <span class="sb-v">{{ doc.name }}</span>
          {%- if one_requester %}
          <span class="sb-sep">|</span>
          <span class="sb-k">{{ _("Requester") }}</span>
          <span class="sb-v">{{ requesters[0] }}</span>
          {%- endif %}
          <span class="sb-sep">|</span>
          <span class="sb-k">{{ _("Status") }}</span>
          <span class="sb-v">
            {%- set st = doc.workflow_state or "" -%}
            {%- if "Reject" in st %}{{ st }}
            {%- elif doc.docstatus != 1 %}{{ _("Pending Approval") }}
            {%- else %}{{ st or _("Approved") }}{% endif -%}
          </span>
        </td>
      </tr>
      <tr>
        <th style="width:12%">{{ _("Date") }}</th>
        <th style="width:16%">{{ _("Shipment") }}</th>
        <th>{{ _("Transactions") }}</th>
        <th class="num" style="width:16%">{{ _("Amount") }} ({{ base_cur }})</th>
        <th class="num" style="width:16%">{{ _("Amount") }} ({{ alt_cur }})</th>
      </tr>
    </thead>
    <tbody>
      {%- for row in rows %}
      {%- set mr_date = frappe.db.get_value("Material Request", row.material_request, "transaction_date") %}
      <tr>
        <td class="reqno">{{ frappe.utils.formatdate(mr_date, "dd.MM.yyyy") if mr_date else "" }}</td>
        <td>{{ row.project or "" }}</td>
        <td>
          <span class="reqno">{{ row.material_request }}</span>
          {%- if row.item_summary or row.description %} - {{ row.item_summary or row.description }}{% endif %}
          {%- if row.employee_name and not one_requester %} <span class="muted">({{ row.employee_name }})</span>{% endif %}
          {%- if row.decision == "Rejected" %}
            <span class="note state state-rejected">{{ _("Rejected") }}{% if row.rejection_reason %}: {{ row.rejection_reason }}{% endif %}</span>
          {%- elif row.decision == "Approved" and row.adjustment_reason %}
            <span class="note">{{ row.adjustment_reason }}</span>
          {%- endif %}
        </td>
        {#- An undecided row has approved_amount 0, which would print as a real
            figure on a sheet someone signs. Show what was asked for until a
            decision exists, and the approved figure once it does. -#}
        {%- set row_amount = (row.approved_amount if row.decision == "Approved" else row.requested_amount) or 0 %}
        {#- The company-currency twin, falling back to the row figure for requests
            raised before multicurrency, where the two are the same number. -#}
        {%- set row_base = (row.base_approved_amount if row.decision == "Approved" else row.base_requested_amount) or (row_amount * (row.exchange_rate or 1)) %}
        <td class="num">{{ frappe.utils.fmt_money(row_base) }}</td>
        <td class="num">{% if row.currency == alt_cur %}{{ frappe.utils.fmt_money(row_amount) }}{% endif %}</td>
      </tr>
      {%- endfor %}
      {%- for _i in range(rows | length, 12) %}
      {#- Blank ruled lines so a short requisition still reads as a form that can
          be written on, which is what the sheet it replaces did. -#}
      <tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>
      {%- endfor %}
      <tr class="subtotal">
        <td>{{ _("Subtotal") }}</td>
        <td></td>
        <td></td>
        <td class="num">{{ frappe.utils.fmt_money(recorded and doc.total_approved or doc.total_requested or 0) }}</td>
        <td class="num">{{ frappe.utils.fmt_money(ns.alt_total) }}</td>
      </tr>
      <tr class="spacer"><td colspan="5"></td></tr>
      <tr class="grand">
        <td></td><td></td>
        <td>{{ _("Grand Total") }} ({{ base_cur }})</td>
        <td class="num">{{ frappe.utils.fmt_money(recorded and doc.total_approved or doc.total_requested or 0) }}</td>
        <td></td>
      </tr>
      <tr class="grand">
        <td></td><td></td>
        <td>{{ _("Grand Total") }} ({{ alt_cur }})</td>
        <td></td>
        <td class="num">{{ frappe.utils.fmt_money(ns.alt_total) }}</td>
      </tr>
    </tbody>
  </table>

  <table class="meta">
    <tr>
      <td><span class="k">{{ _("Requests") }}</span> {{ rows | length }}{% if rejected_rows %} ({{ rejected_rows | length }} {{ _("rejected") }}){% endif %}</td>
      {#- Plain number with the currency named, matching the money columns above.
          The symbol form printed "Sh 0.00" next to columns headed (KES). -#}
      <td><span class="k">{{ _("Disbursed") }}</span> {{ base_cur }} {{ frappe.utils.fmt_money(doc.total_funded or 0) }}</td>
    </tr>
  </table>

  {%- if doc.remarks %}
  <div class="remarks"><span class="k">{{ _("Remarks") }}</span><div>{{ doc.remarks }}</div></div>
  {%- endif %}

  <table class="sigs">
    <tr>
      <td>
        <div class="sig-space"></div>
        <div class="sig-line">
          <span class="sig-role">{{ _("Requested by") }}</span>
          <span class="sig-name">{{ frappe.db.get_value("User", doc.submitted_by, "full_name") or doc.submitted_by or "&nbsp;" }}</span>
          <span class="sig-hint">{{ _("Signature and date") }}</span>
        </div>
      </td>
      <td>
        <div class="sig-space"></div>
        <div class="sig-line">
          <span class="sig-role">{{ _("Approved by") }}</span>
          <span class="sig-name">{{ frappe.db.get_value("User", doc.approved_by, "full_name") or doc.approved_by or "&nbsp;" }}</span>
          <span class="sig-hint">{% if doc.approval_date %}{{ frappe.utils.formatdate(doc.approval_date, "dd.MM.yyyy") }}{% else %}{{ _("Signature and date") }}{% endif %}</span>
        </div>
      </td>
      <td>
        <div class="sig-space"></div>
        <div class="sig-line">
          <span class="sig-role">{{ _("Disbursed by") }}</span>
          <span class="sig-name">&nbsp;</span>
          <span class="sig-hint">{{ _("Signature and date") }}</span>
        </div>
      </td>
    </tr>
  </table>

</div>
